insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-213', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'In $2\mathrm{A} + \mathrm{B} \to \mathrm{C}$, if A disappears at $6.0 \times 10^{-3}\ \mathrm{mol\ L^{-1}\ s^{-1}}$, C appears at', '["$3.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$6.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.2 \\times 10^{-2}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.5 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$"]'::jsonb, 0, 'Rate $= -\tfrac12 \mathrm{d}[\mathrm{A}]/\mathrm{d}t = +\mathrm{d}[\mathrm{C}]/\mathrm{d}t$, so d[C]/dt is half of 6.0 × 10$^{-3}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'rate-law') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
