insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-214', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Holding [B] fixed, [A] is doubled and the initial rate becomes four times larger. The order with respect to A is', '["2","1","0","4"]'::jsonb, 0, 'rate ∝ [A]$^x$ and $4 = 2^x$ implies $x = 2$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'rate-law') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
