insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-216', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Rate $= k[\mathrm{NO}]^2[\mathrm{O_2}]$ with $k = 1.0 \times 10^3\ \mathrm{L^2\ mol^{-2}\ s^{-1}}$. If [NO] = 0.020 M and [O$_2$] = 0.010 M, the rate is', '["$4.0 \\times 10^{-3}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$4.0 \\times 10^{-6}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$2.0 \\times 10^{-4}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$","$1.0 \\times 10^{-2}\\ \\mathrm{mol\\ L^{-1}\\ s^{-1}}$"]'::jsonb, 0, 'Rate $= 1.0 \times 10^3 \times (0.020)^2 \times 0.010 = 1.0 \times 10^3 \times 4.0 \times 10^{-6} = 4.0 \times 10^{-3}\ \mathrm{mol\ L^{-1}\ s^{-1}}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'rate-law') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
