insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-217', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'The order of a reaction may be zero or fractional, whereas molecularity is', '["a positive integer (1, 2 or occasionally 3) for an elementary step","always equal to zero","allowed to be negative for unimolecular decays","undefined for every elementary reaction"]'::jsonb, 0, 'Order is experimental and can be 0, ½, 1, 2, …. Molecularity counts the molecules in one elementary act and is a small integer.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'order-molecularity') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
